mapper.select:
SELECT DISTINCT b.tenant_id,b.tenant_name as customer_name,o.is_operation as isOperation,osl.app_ver_code,osl.industry_code, GROUP_CONCAT( IF ( o.operation_type = '2', o.operation_alarm_type_str, null) ) AS parallel_alarm_type_str, GROUP_CONCAT( IF ( o.operation_type = '1', o.operation_alarm_type_str, null) ) AS serial_alarm_type_str, GROUP_CONCAT( o.operation_type ) AS operation_type, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '2' THEN o.operation_node END, '' )) AS parallelOperationNode, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '1' THEN o.operation_node END, '' )) AS operationNode, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '2' THEN o.operation_dept END, '' )) AS parallelOperationDept, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '1' THEN o.operation_dept END, '' )) AS operationDept, GROUP_CONCAT(o.alarm_source) AS operation_alarm_source FROM sys_tenant_info b INNER JOIN vm_order_services_rel osl ON b.tenant_id = osl.tenant_id LEFT JOIN sys_tenant_operation_config o ON o.tenant_id = b.tenant_id and o.industry_code = osl.industry_code AND (o.alarm_source = '9' or o.alarm_source = '-1')
and o.accept_node = #{localNode}
AND o.delete_flag = '0' WHERE osl.ord_status in (0, 1, 2)
and osl.accept_node = #{localNode}
AND osl.service_code = '9' AND osl.delete_flag = '0'
AND osl.provice_code = #{province}
AND osl.city_code = #{city}
AND osl.county_code = #{county}
GROUP BY b.tenant_id,osl.industry_code

SELECT DISTINCT accept_node FROM `vm_order_services_rel` WHERE delete_flag = '0' AND service_code = '9' AND ord_status IN ( '0', '1', '2' ) and provice_code = #{province} and city_code = #{city} and county_code = #{county} AND accept_node != '10000000001'
AND accept_node IN
#{item}
